insert into public.questions
  (id, module, domain, skill, difficulty, passage, prompt, choices, answer, explanation, choice_explanations)
values
  ($q$conv-210$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The new recipe contains______sugar than the original version.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["less","fewer","lesser","little"]$q$::jsonb, 0, $q$'Sugar' is a noncount (mass) noun, so the noncount modifier 'less' is required rather than 'fewer,' which modifies countable plural nouns.$q$, null),
  ($q$conv-211$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The new tax policy had a significant______on small businesses.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["effect","affect","effects","affecting"]$q$::jsonb, 0, $q$'Effect' is the noun meaning 'a result,' which fits the sentence; 'affect' is primarily a verb meaning 'to influence.'$q$, null),
  ($q$conv-212$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The results of the second exam were better______anyone had predicted.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["than","then","that","when"]$q$::jsonb, 0, $q$'Than' is used to introduce a comparison; 'then' refers to time and does not fit this context.$q$, null),
  ($q$conv-213$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Someone left______umbrella in the lobby after the meeting.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$With an indefinite singular antecedent like 'someone' whose gender is unspecified, Standard English uses the pronoun 'their'; 'its' is reserved for things, not people.$q$, null),
  ($q$conv-214$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the critic arrived, the chef______the entire tasting menu.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had already prepared","would have prepared","has already prepared","was already preparing"]$q$::jsonb, 0, $q$Because the menu was prepared before another past event (the critic's arrival), the past perfect 'had already prepared' is required; 'would have prepared' is tempting because it also links two past events, but the conditional perfect wrongly implies the preparation depended on some unstated condition.$q$, null),
  ($q$conv-215$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The teacher insisted that each student______their essay before the deadline.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["submit","submits","submitted","will submit"]$q$::jsonb, 0, $q$'Insisted that' triggers the subjunctive mood, which uses the base form 'submit' regardless of the subject's number; 'submits' is tempting because it matches the singular 'student,' but subjunctive clauses do not follow ordinary subject-verb agreement.$q$, null),
  ($q$conv-216$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Hoping to capture the eclipse, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the photographer set up her tripod before dawn.","the tripod stood ready on the hillside before dawn.","dawn broke just as the eclipse began.","careful planning made the early morning shoot possible."]$q$::jsonb, 0, $q$The introductory phrase 'Hoping to capture the eclipse' describes a person, so the noun immediately after the comma must be that person, 'the photographer'; the tripod, the dawn, and the planning cannot hope, even though each choice is a complete, sensible sentence on its own.$q$, null),
  ($q$conv-217$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$There______dozens of species native to this single valley.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$The subject that follows, 'dozens of species,' is plural, so the verb must agree with it: 'are.'$q$, null),
  ($q$conv-218$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The committee could not agree on______to send to the conference.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","whoever","which"]$q$::jsonb, 0, $q$The pronoun functions as the object of the infinitive 'to send,' so the objective case 'whom' is required, not the subjective 'who.'$q$, null),
  ($q$conv-219$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new curriculum aims both to challenge advanced students and to______struggling ones.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["support","supporting","the support of","supportive of"]$q$::jsonb, 0, $q$'Both...and' requires parallel structure; since the first element is the infinitive 'to challenge,' the second must match with the base verb 'support' after 'to.'$q$, null),
  ($q$conv-220$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The two attorneys agreed to discuss the settlement______before presenting it to the judge.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["further","farther","furthest","farthest"]$q$::jsonb, 0, $q$'Further' refers to figurative or additional extent, which fits this context, while 'farther' is generally reserved for physical distance.$q$, null),
  ($q$conv-221$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Because the blacksmith tempered the blade slowly______the metal gained unusual flexibility.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Because the blacksmith tempered the blade slowly' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-222$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Measuring the hem twice before cutting______the tailor avoided a costly mistake.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Measuring the hem twice before cutting' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-223$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The vineyard's harvest was delayed by a week of rain______workers picked the grapes in a single frantic weekend.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-224$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The subway line lost signal power downtown______riders waited on the platform for nearly an hour.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with no coordinating conjunction must be joined with a semicolon rather than a comma, which would create a comma splice.$q$, null),
  ($q$conv-225$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The greenhouse cultivates three varieties of orchid______the moth orchid, the lady's slipper, and the vanda.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-226$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The cartographer discovered the error at last______the coastline had been drawn nearly a mile off.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the error was, following a complete independent clause.$q$, null),
  ($q$conv-227$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The turbine, ______ stands nearly four hundred feet tall, generates enough power for two thousand homes.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the turbine, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-228$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Chisels______left out in the rain overnight had begun to rust by morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Left out in the rain overnight' is a restrictive (essential) phrase identifying which chisels are meant, so no comma is needed before it.$q$, null),
  ($q$conv-229$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The bylaw______the board passed by a single vote takes effect next month.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'the board passed by a single vote' is essential to identifying which bylaw is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct.$q$, null),
  ($q$conv-230$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The scholarship is awarded to______the selection committee judges most committed to public service.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whomever","whoever","whom","who"]$q$::jsonb, 0, $q$Within the clause, the pronoun functions as the object of 'judges' ('the committee judges whom'), so the objective case 'whomever' is required even though the whole clause follows the preposition 'to'; 'whoever' is the closest trap because it would be correct if the pronoun were the subject of 'judges' rather than its object.$q$, null),
  ($q$conv-231$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The party selected a candidate______voters already trusted.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","whoever","whomever"]$q$::jsonb, 0, $q$The pronoun is the object of 'trusted' ('voters trusted whom'), so the objective case 'whom' is correct.$q$, null),
  ($q$conv-232$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The company's new headquarters______a repurposed textile mill dating to the 1890s, complete with its original smokestack—opened to employees six months ahead of schedule.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a repurposed textile mill dating to the 1890s, complete with its original smokestack' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-233$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The senator's proposal______a modest increase in the minimum wage, phased in over three years—drew fierce opposition from business groups.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a modest increase in the minimum wage, phased in over three years' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-234$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The gem's one imperfection______a faint cloud near its center, visible only under magnification—reduced its appraised value significantly.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a faint cloud near its center, visible only under magnification' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-235$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The architect's final sketch______a sweeping glass atrium flooded with light from a retractable roof—became the building's most celebrated feature.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a sweeping glass atrium flooded with light from a retractable roof' is a single nonessential aside about the sketch, so only a matching dash—not a comma, colon, or semicolon—can open it without being mistaken for a new independent clause.$q$, null),
  ($q$conv-236$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The factory's output rose sharply after the upgrade______however, training for the new machines lagged behind.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'However' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-237$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The clinic's wait times grew longer every month______moreover, several nurses resigned in frustration.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Moreover' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-238$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Sales slowed on the east coast throughout the winter______meanwhile, the western branch posted record numbers.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Meanwhile' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-239$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The cruise ship departed ten minutes late______but it still reached the harbor before the tide turned.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'But' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-240$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The students could present their findings in class______or they could submit a written report instead.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Or' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-241$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After the stagehands finished setting the props______the actors ran through their final scene.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After the stagehands finished setting the props' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-242$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Weighed down by a stack of packages______the courier struggled up the icy steps.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Weighed down by a stack of packages' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-243$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Once the auditors finished reviewing the accounts______they flagged three irregular transactions.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Once the auditors finished reviewing the accounts' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-244$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Despite months of careful planning______the product launch was postponed at the last minute.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Despite months of careful planning' is an introductory prepositional phrase and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-245$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The printing press broke down twice during the run______the morning edition still reached every newsstand on time.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-246$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The region's main reservoir dropped to half its usual level______farmers downstream began rationing irrigation water.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with no coordinating conjunction must be joined with a semicolon rather than a comma, which would create a comma splice.$q$, null),
  ($q$conv-247$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The new phone's reviews were mixed at best______pre-orders still shattered the company's previous sales record.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with a contrast in meaning but no coordinating conjunction must be joined with a semicolon.$q$, null),
  ($q$conv-248$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$A software bug disabled the booking system for six hours______call-center staff processed every reservation by hand.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction joining them, so a semicolon is required; a comma alone would create a comma splice.$q$, null),
  ($q$conv-249$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The hardware store restocked three essential items before the storm______batteries, bottled water, and plywood.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-250$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The conference featured three keynote speakers______Dr. Hassan, an immunologist; Ms. Okafor, a biostatistician; and Mr. Weiss, a public policy advisor.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list following the complete independent clause; because the items themselves contain commas, semicolons separate the items, but only a colon can introduce the list as a whole.$q$, null),
  ($q$conv-251$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The investigators reached a single conclusion after months of analysis______the leak had originated in the server room.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the conclusion was, following a complete independent clause; the semicolon is the closest trap because it could also join these two independent clauses, but it lacks the colon's specific signal that what follows defines or explains the conclusion just mentioned.$q$, null),
  ($q$conv-252$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The treaty, ______ took nearly a decade to negotiate, finally ended the dispute over fishing rights.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the treaty, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-253$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The dam, ______ operating continuously since 1950 under the supervision of a single engineering firm, underwent its first major inspection last year.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which has been","that has been","who has been","being"]$q$::jsonb, 0, $q$The nonessential clause set off by commas describes a thing (the dam), not the firm mentioned later in the sentence, so it needs the thing-pronoun 'which' with a complete verb phrase; 'who has been' is tempting because an organization of people is mentioned nearby, but the clause still modifies 'dam.'$q$, null),
  ($q$conv-254$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Only the nurses______had completed the advanced certification were assigned to the trauma unit.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","who, ",", who",", who,"]$q$::jsonb, 0, $q$The clause 'who had completed the advanced certification' is essential (restrictive) to identifying which nurses are meant, so it takes no surrounding commas.$q$, null),
  ($q$conv-255$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The choir______every Tuesday evening in the chapel basement.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["practices","practice","have practiced","are practicing"]$q$::jsonb, 0, $q$'Choir' is a singular collective noun, so it takes the singular verb 'practices.'$q$, null),
  ($q$conv-256$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Nobody on the construction crew______aware of the schedule change until the foreman announced it.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$The indefinite pronoun 'nobody' is grammatically singular, so it takes the singular verb 'was.'$q$, null),
  ($q$conv-257$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$One of the paintings in the gallery______damaged during shipping.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$The subject of the sentence is the singular pronoun 'one,' not the object of the preposition 'paintings,' so the singular verb 'was' is correct.$q$, null),
  ($q$conv-258$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Neither the pilot nor the flight attendants______informed of the delay until boarding had already begun.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In 'neither...nor' constructions, the verb agrees with the nearer subject. Since 'flight attendants' (plural) is nearer, the plural verb 'were' is correct.$q$, null),
  ($q$conv-259$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Either the landlord or the tenants______responsible for the fence repair when the inspector visited last week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In an 'either/or' construction, the verb agrees with the nearer subject, 'tenants,' which is plural, so 'were' is correct.$q$, null),
  ($q$conv-260$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$A number of volunteers______already signed up for the weekend cleanup.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have","has","having","is"]$q$::jsonb, 0, $q$'A number of' is treated as plural, so it takes the plural verb 'have'; this differs from 'the number of,' which takes a singular verb.$q$, null),
  ($q$conv-261$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The number of applicants this year______higher than last year's total.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$'The number of' is treated as singular, so it takes the singular verb 'is'; this differs from 'a number of,' which takes a plural verb.$q$, null),
  ($q$conv-262$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Ten minutes______plenty of time to cross the busy intersection safely, according to the crossing guard.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$When a span of time is treated as a single unit rather than individual minutes, it takes a singular verb, so 'is' is correct.$q$, null),
  ($q$conv-263$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The passengers gathered______belongings before exiting the train.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'passengers' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-264$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The task force submitted______recommendations to the governor.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","their","his","one's"]$q$::jsonb, 0, $q$'Task force' functions as a singular collective noun acting as one unit, so it takes the singular possessive 'its,' not the plural 'their.'$q$, null),
  ($q$conv-265$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The award was shared equally between the lead engineer and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","I","myself","us"]$q$::jsonb, 0, $q$The pronoun is the object of the preposition 'between,' so the objective case 'me' is correct, not the subjective 'I.' 'Myself' is the closest trap because reflexive pronouns are often used this way in casual speech, but 'myself' needs an earlier 'I' in the same clause to reflect back to, which is missing here.$q$, null),
  ($q$conv-266$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The director asked the lead actor and______to rehearse the final scene privately.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","I","myself","us"]$q$::jsonb, 0, $q$The pronoun is the object of 'asked,' so the objective case 'me' is correct, not the subjective 'I.' 'Myself' is the closest trap for the same reason: reflexive pronouns are common in casual speech here, but 'myself' needs an earlier 'I' in the clause to reflect back to.$q$, null),
  ($q$conv-267$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The interns completed the audit by______, without any supervision.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["themselves","theirselves","their self","them"]$q$::jsonb, 0, $q$The plural reflexive pronoun 'themselves' correctly refers back to 'the interns.' 'Them' is the closest trap because it is a real plural pronoun, but the sentence needs the reflexive form to show the interns acted on their own, not a plain object pronoun.$q$, null),
  ($q$conv-268$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the ambulance arrived, the paramedic______the bleeding.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had already stopped","already stopped","have already stopped","were already stopping"]$q$::jsonb, 0, $q$Because the bleeding was stopped before another past event (the ambulance's arrival), the past perfect 'had already stopped' is required.$q$, null),
  ($q$conv-269$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the lease ends, the tenants______in the apartment for exactly five years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["will have been living","will live","lived","are living"]$q$::jsonb, 0, $q$'By the time' with a future event signals the future perfect progressive tense, 'will have been living,' to show an action continuing up to that future point; 'will live' is tempting because it is also future tense, but it lacks the progressive aspect needed to show the five-year duration.$q$, null),
  ($q$conv-270$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Technicians______the pipeline for leaks since the inspection began, and they have found none so far.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have examined","examined","examine","will examine"]$q$::jsonb, 0, $q$The action began in the past and continues into the present ('since...have found'), so the present perfect 'have examined' is correct.$q$, null),
  ($q$conv-271$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The physician recommended that the patient______more water each day.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["drink","drinks","will drink","drank"]$q$::jsonb, 0, $q$'Recommended that' triggers the subjunctive mood, which uses the base form of the verb ('drink') regardless of the subject's number.$q$, null),
  ($q$conv-272$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If the forecast______accurate, the festival organizers would have moved the event indoors.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had been","was","were","has been"]$q$::jsonb, 0, $q$The main clause 'would have moved' signals a past unreal conditional, which requires the past perfect 'had been' in the if-clause. 'Were' is the closest trap because it is the correct subjunctive form for a present contrary-to-fact condition, but this sentence is about a past, completed event, which needs the past perfect instead.$q$, null),
  ($q$conv-273$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Last winter, the crew cleared the trail and______three fallen trees along the way.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["removed","removes","will remove","removing"]$q$::jsonb, 0, $q$The sentence is in past tense ('cleared'), so the second verb must also be past tense, 'removed,' to remain consistent.$q$, null),
  ($q$conv-274$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Squinting against the glare off the snow, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the skier adjusted her goggles before the next run.","her goggles fogged up within minutes of the start.","the next run promised even brighter glare off the snow.","sunlight reflected sharply off the fresh snow."]$q$::jsonb, 0, $q$The introductory phrase 'Squinting against the glare off the snow' describes a person, so the noun immediately after the comma must be that person, 'the skier'; the goggles, the run, and the sunlight cannot squint, even though each choice forms a complete, plausible sentence.$q$, null),
  ($q$conv-275$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Eager to beat the closing bell, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the trader placed one last order.","one last order was placed by the trader.","the closing bell prompted one last order.","the stock exchange recorded one last order."]$q$::jsonb, 0, $q$The introductory phrase 'Eager to beat the closing bell' describes a person, not the order or the exchange, so the noun immediately following the comma must be 'the trader.'$q$, null),
  ($q$conv-276$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Freshly painted and still smelling of varnish, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the fence looked brand new to the neighbors.","the neighbors admired the fence.","varnish was smelled by the neighbors.","a brand-new look was given to the fence."]$q$::jsonb, 0, $q$The introductory phrase 'Freshly painted and still smelling of varnish' describes the fence, so the noun immediately following the comma must be 'the fence.'$q$, null),
  ($q$conv-277$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Her daily routine includes feeding the chickens, mending fences, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["chopping firewood","to chop firewood","she chops firewood","firewood is chopped"]$q$::jsonb, 0, $q$The list requires parallel gerunds ('feeding,' 'mending,' and ___), so 'chopping firewood' matches the established form.$q$, null),
  ($q$conv-278$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The reviewers described the novel as ambitious, moving, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["beautifully written","written with beauty","beauty in writing","the writing was beautiful"]$q$::jsonb, 0, $q$The list requires parallel adjective phrases ('ambitious, moving, and ___'), and 'beautifully written' matches that adjectival form.$q$, null),
  ($q$conv-279$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The grant supports not only scientists studying climate change but also______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["policymakers drafting new regulations","the drafting of new regulations by policymakers","policymakers who draft new regulations","regulations drafted by policymakers"]$q$::jsonb, 0, $q$'Not only...but also' pairs two objects of 'supports'; since the first is the noun-plus-participle phrase 'scientists studying climate change,' the second must match that exact form: 'policymakers drafting new regulations.' The other choices are grammatical noun phrases but use a gerund, a full relative clause, or a passive participle instead, so they do not match the original construction.$q$, null),
  ($q$conv-280$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new software is designed both to streamline billing and to______customer complaints.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["reduce","reducing","the reduction of","reduction in"]$q$::jsonb, 0, $q$'Both...and' requires parallel structure; since the first element is the infinitive 'to streamline,' the second must match with the base verb 'reduce' after 'to.'$q$, null),
  ($q$conv-281$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Between the two job offers, the smaller firm's offer was the______generous.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more","most","much","many"]$q$::jsonb, 0, $q$When comparing exactly two things, the comparative form 'more' is required rather than the superlative 'most,' which is used for three or more.$q$, null),
  ($q$conv-282$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new engine produces more torque than______engine in its class.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["any other","any","all","every"]$q$::jsonb, 0, $q$Because the engine is itself a member of its class, it must be compared to 'any other engine' to exclude itself from the comparison. 'Any' is the closest trap because it almost completes the idiom correctly, but without 'other' it illogically includes the engine among the things it is being compared to.$q$, null),
  ($q$conv-283$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After the telescope was recalibrated______astronomers detected the faint signal again.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After the telescope was recalibrated' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-284$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The bridge had been closed for repairs______traffic backed up for miles every morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-285$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The chef finally revealed the secret to the dish's flavor______a generous spoonful of smoked paprika.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the secret was, following a complete independent clause.$q$, null),
  ($q$conv-286$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Volunteers______who arrive before sunrise will help set up the aid station.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Who arrive before sunrise' is a restrictive clause identifying which volunteers, so no comma should separate it from the noun it modifies.$q$, null),
  ($q$conv-287$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The violin, ______ had belonged to her grandmother, was insured for an enormous sum.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential, set off by commas, and refers to a thing, the violin, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-288$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The satellite lost contact with mission control______however, engineers restored the signal within an hour.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$A conjunctive adverb like 'however' joining two independent clauses requires a semicolon before it and a comma after it.$q$, null),
  ($q$conv-289$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Startled by the sudden thunder______the horses bolted across the pasture.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Startled by the sudden thunder' is an introductory participial phrase and must be followed by a comma.$q$, null),
  ($q$conv-290$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The archive digitized thousands of brittle documents______researchers could finally search them by keyword.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," and, ",": "]$q$::jsonb, 0, $q$Two independent clauses with no conjunction must be joined with a semicolon; linking them with only a comma would create a comma splice.$q$, null),
  ($q$conv-291$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The expedition packed only the essentials______a tent, a water filter, and a satellite phone.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items that follows the complete independent clause.$q$, null),
  ($q$conv-292$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Beneath the city's oldest cathedral______archaeologists discovered a network of sealed tunnels.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Beneath the city's oldest cathedral' is an introductory phrase and requires a comma before the main clause.$q$, null),
  ($q$conv-293$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The lighthouse keeper______a quiet man who, by his own account, rarely left the island—kept meticulous weather logs for forty years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a quiet man who, by his own account, rarely left the island' already contains internal commas, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-294$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The survey revealed one clear trend______younger voters overwhelmingly preferred mail-in ballots.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ",", ","; "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of the trend, following a complete independent clause.$q$, null),
  ($q$conv-295$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The museum's rarest exhibit______a 400-year-old astrolabe, draws visitors from around the world.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$The appositive 'a 400-year-old astrolabe' is nonessential and already closed with a comma, so it must be opened with a matching comma.$q$, null),
  ($q$conv-296$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Interest rates fell sharply last quarter______consumer borrowing rose for the first time in years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both clauses are independent and closely related, so a semicolon correctly joins them without a coordinating conjunction.$q$, null),
  ($q$conv-297$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The sprinter crossed the finish line______and immediately collapsed from exhaustion.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Crossed the finish line' and 'collapsed from exhaustion' share the same subject and form a compound predicate, so no comma is needed before 'and.' The comma is the closest trap because commas do precede 'and' when it joins two independent clauses, but here 'and' only joins two verbs sharing one subject.$q$, null),
  ($q$conv-298$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The app crashed repeatedly______so the developers rushed out an emergency patch.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$A comma is required before the coordinating conjunction 'so' when it joins two independent clauses.$q$, null),
  ($q$conv-299$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The CEO's turnaround strategy came down to one word______focus.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon can introduce a single word for emphasis when it follows a complete independent clause; the comma is the closest trap because it could loosely connect 'one word' and 'focus' in casual writing, but formal Standard English calls for the colon's stronger emphasis after a complete clause like this one.$q$, null),
  ($q$conv-300$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Its wings folded tightly against its body______the falcon plummeted toward its prey.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Its wings folded tightly against its body' is an introductory absolute phrase and must be followed by a comma.$q$, null),
  ($q$conv-301$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The manuscript______that the librarian found in a sealed box turned out to be a lost first draft.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'That the librarian found in a sealed box' is a restrictive clause identifying which manuscript, so it takes no comma.$q$, null),
  ($q$conv-302$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The sculptor, ______ had never formally studied art, won the competition's top prize.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","that","whom","which"]$q$::jsonb, 0, $q$The nonessential clause set off by commas refers to a person and functions as the subject of 'had never studied,' so the subject pronoun 'who' is correct.$q$, null),
  ($q$conv-303$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The control group showed no measurable change______therefore, the researchers concluded the treatment was ineffective.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$A conjunctive adverb like 'therefore' joining two independent clauses requires a semicolon before it and a comma after it.$q$, null),
  ($q$conv-304$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The tower's spire—reconstructed using the original fifteenth-century blueprints, which had sat forgotten in a monastery archive______finally returned to the skyline after a decade of restoration.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'reconstructed using the original fifteenth-century blueprints, which had sat forgotten in a monastery archive' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can close the interruption without creating ambiguity about where the aside ends.$q$, null),
  ($q$conv-305$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$To avoid the morning rush______she started leaving for work an hour earlier.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'To avoid the morning rush' is an introductory infinitive phrase and must be followed by a comma.$q$, null),
  ($q$conv-306$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Before the storm hit, they stocked up on the basics______water, batteries, and canned food.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items that follows the complete independent clause.$q$, null),
  ($q$conv-307$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The prototype, ______ took engineers nearly three years to perfect, finally entered mass production.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential, set off by commas, and refers to a thing, the prototype, so 'which' is correct; 'that' introduces restrictive clauses only.$q$, null),
  ($q$conv-308$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Glacial melt accelerated throughout the decade______coastal cities began investing heavily in sea walls.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Two independent clauses with no coordinating conjunction must be joined by a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-309$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The post went viral within hours______the company's marketing team had not even finished drafting a response.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction, so they must be separated by a semicolon rather than joined with only a comma. The comma is the closest trap because a comma plus a coordinating conjunction like 'so' could join these clauses, but a bare comma alone creates a comma splice.$q$, null),
  ($q$conv-310$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Although the treaty was signed within weeks of the ceasefire______many of its provisions were not enforced for years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Although the treaty was signed within weeks of the ceasefire' is an introductory dependent clause and must be followed by a single comma. The semicolon is the closest trap because semicolons do separate clauses elsewhere in similar sentences, but a semicolon requires an independent clause on both sides, and this opening clause is dependent.$q$, null),
  ($q$conv-311$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Critics agreed on the mural's central flaw______the perspective collapsed entirely in the lower-left corner.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the flaw was, following a complete independent clause; the semicolon is the closest trap because it could also join these two independent clauses, but it lacks the colon's specific signal that what follows defines or explains the flaw just mentioned.$q$, null),
  ($q$conv-312$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The research team______preparing its final report for the grant committee.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$'Team' is a singular collective noun, so it takes the singular verb 'is.'$q$, null),
  ($q$conv-313$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Each of the students______expected to submit a lab notebook at the end of the semester.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$'Each' is singular, regardless of the plural noun in the prepositional phrase that follows it, so the singular verb 'is' is correct.$q$, null),
  ($q$conv-314$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Neither the manager nor the players______happy with the umpire's final call.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In a 'neither/nor' construction, the verb agrees with the nearer subject, 'players,' which is plural, so 'were' is correct.$q$, null),
  ($q$conv-315$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The collection of rare orchids in the botanical garden's east wing______watered by hand every morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$The subject is the singular noun 'collection'; the prepositional phrases that follow do not change its number, so the singular verb 'is' is correct.$q$, null),
  ($q$conv-316$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the train arrives, she______on the platform for nearly two hours.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["will have been waiting","will wait","waited","is waiting"]$q$::jsonb, 0, $q$'By the time' with a future event signals the future perfect progressive tense, 'will have been waiting,' to show an action continuing up to that future point; 'will wait' is tempting because it is also future tense, but it lacks the progressive aspect needed to show the two-hour duration.$q$, null),
  ($q$conv-317$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The criteria for approving the new drug______far stricter than those used a decade ago.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$'Criteria' is the plural form of 'criterion,' so it takes the plural verb 'are.'$q$, null),
  ($q$conv-318$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The hikers left______water bottles at the trailhead by mistake.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'hikers' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-319$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The startup announced that______new app would launch nationwide next month.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","it's","its'","their"]$q$::jsonb, 0, $q$The possessive form 'its' (no apostrophe) is required here, not the contraction 'it's,' which means 'it is.'$q$, null),
  ($q$conv-320$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The neighbors said______planning to repaint the fence over the long weekend.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["they're","their","there","there's"]$q$::jsonb, 0, $q$'They're' is the contraction for 'they are' and is needed before the verb 'planning'; 'their' and 'there' are homophones that do not fit this grammatical role.$q$, null),
  ($q$conv-321$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The detective finally identified______the witness had seen leaving the building.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","whoever","whomever"]$q$::jsonb, 0, $q$'Whom' is the object of the verb 'had seen' ('the witness had seen whom'), so the object pronoun is required rather than the subject pronoun 'who.'$q$, null),
  ($q$conv-322$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Migrating thousands of miles each winter, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the arctic tern travels farther than almost any other bird.","the journey of the arctic tern spans nearly the length of the globe.","scientists have long studied the arctic tern's migration patterns.","pole-to-pole flight paths make the arctic tern famous among researchers."]$q$::jsonb, 0, $q$The introductory phrase 'Migrating thousands of miles each winter' describes a traveler, so the subject of the main clause must be the one migrating, 'the arctic tern'; the journey, the scientists, and the flight paths do not themselves migrate, even though each choice is a grammatically complete sentence.$q$, null),
  ($q$conv-323$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The exhibit celebrates artists who not only reshaped modern sculpture but also______entire movements in architecture.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["inspired","inspiring","have been inspiring","the inspiration of"]$q$::jsonb, 0, $q$'Not only...but also' requires parallel structure; since the first element is the past-tense verb 'reshaped,' the second must match with 'inspired.'$q$, null),
  ($q$conv-324$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new platform is designed both to simplify checkout and to______fraud in real time.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["flag","flagging","the flagging of","flags"]$q$::jsonb, 0, $q$'Both...and' requires parallel structure; since the first element is the infinitive 'to simplify,' the second must match with the base verb 'flag' after 'to.'$q$, null),
  ($q$conv-325$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Of the two apartments they toured, the one downtown was the______expensive.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more","most","much","many"]$q$::jsonb, 0, $q$When comparing exactly two things, the comparative form 'more' is required rather than the superlative 'most,' which is reserved for three or more.$q$, null),
  ($q$conv-326$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$This processor runs cooler than______chip in its price range.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["any other","any","all","every"]$q$::jsonb, 0, $q$Because the processor is itself a member of its price range, it must be compared to 'any other chip' to exclude itself from the comparison. 'Any' is the closest trap because it almost completes the idiom correctly, but without 'other' it illogically includes the processor among the things it is being compared to.$q$, null),
  ($q$conv-327$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The______uniforms were donated to the regimental museum after the ceremony.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["soldiers'","soldier's","soldiers's","soldiers"]$q$::jsonb, 0, $q$Because the uniforms belong to multiple soldiers, the plural possessive 'soldiers'' (apostrophe after the s) is required.$q$, null),
  ($q$conv-328$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$No one could identify______umbrella had been left behind in the lecture hall.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whose","who's","whom's","who is"]$q$::jsonb, 0, $q$The possessive 'whose' is needed to show ownership of the umbrella; 'who's' is a contraction of 'who is' and does not fit here.$q$, null),
  ($q$conv-329$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$By the time help arrived, the pipe had already______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["burst","bursted","bursting","burst'd"]$q$::jsonb, 0, $q$'Burst' is an irregular verb whose past participle is identical to its base form; 'bursted' is a nonstandard form.$q$, null),
  ($q$conv-330$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Scattered across the hillside______dozens of wildflowers no one had planted.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$The sentence is inverted, but the subject is still the plural noun 'wildflowers,' which follows the verb, so the plural verb 'were' is required. 'Was' is the closest trap because a reader might wrongly treat 'hillside' in the opening phrase as the subject instead of the actual subject that follows the verb.$q$, null),
  ($q$conv-331$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$My brother and______decided to repaint the garage over the weekend.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["I","me","myself","us"]$q$::jsonb, 0, $q$'My brother and I' functions as the subject of the sentence, so the subject pronoun 'I' is required rather than the object pronoun 'me.'$q$, null),
  ($q$conv-332$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The treaty established new borders and______the region's first independent currency.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["created","creates","creating","will create"]$q$::jsonb, 0, $q$The sentence describes past events, so the verb must stay in the past tense, 'created,' to match 'established.'$q$, null),
  ($q$conv-333$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The firm's new policy focuses on reducing waste and______employee morale.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["improving","to improve","improves","improvement of"]$q$::jsonb, 0, $q$The verb 'focuses on' takes the gerund 'reducing,' so the second item in the series must match with the parallel gerund 'improving.'$q$, null),
  ($q$conv-334$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The last person to leave the laboratory that night was______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["she","her","herself","hers"]$q$::jsonb, 0, $q$The pronoun follows the linking verb 'was' and renames the subject, so the subject-case pronoun 'she' is required rather than the object-case 'her.' 'Her' is the closest trap because it is the pronoun most people default to after a verb, but a linking verb takes a subject-case complement, not an object.$q$, null),
  ($q$conv-335$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$She is one of the few researchers who______ever successfully cloned this species of coral.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have","has","having","is having"]$q$::jsonb, 0, $q$The relative clause 'who have ever successfully cloned' modifies 'researchers,' a plural noun, so the plural verb 'have' is required. 'Has' is the closest trap because a reader might wrongly match the verb to the singular 'she' instead of to 'researchers,' the actual antecedent of 'who.'$q$, null),
  ($q$conv-336$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The manager asked Priya and______to present the quarterly report.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","myself","I","mine"]$q$::jsonb, 0, $q$The pronoun is the object of the verb 'asked,' so the object pronoun 'me' is required; 'myself' cannot substitute for 'me' without a prior reference to the speaker in the same clause.$q$, null),
  ($q$conv-337$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$A number of employees______requested the option to work remotely on Fridays.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have","has","having","is"]$q$::jsonb, 0, $q$'A number of' is followed by a plural verb because the emphasis is on the individual employees, unlike 'the number of,' which takes a singular verb. 'Has' is the closest trap because it would be correct if the phrase were 'the number of employees,' which treats the group as one unit rather than as individuals.$q$, null),
  ($q$conv-338$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The baker and the florist______next door to each other for twenty years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have worked","has worked","working","works"]$q$::jsonb, 0, $q$'The baker and the florist' is a compound subject joined by 'and,' so it requires the plural verb 'have worked.'$q$, null),
  ($q$conv-339$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Either the twins or their cousin______bringing dessert to the reunion.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$In an 'either/or' construction, the verb agrees with the nearer subject, the singular 'cousin,' so 'is' is correct.$q$, null),
  ($q$conv-340$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The charity renovated the______playground behind the old shelter.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["children's","childrens'","childs'","children"]$q$::jsonb, 0, $q$'Children' is already plural, so its possessive form adds only an apostrophe and s: 'children's'; 'childrens'' incorrectly treats 'children' as if it ended in s.$q$, null),
  ($q$conv-341$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$She should______the form before the deadline.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["submit","submits","to submit","submitting"]$q$::jsonb, 0, $q$The modal verb 'should' must be followed by the base form of the verb, 'submit,' not an inflected or infinitive form.$q$, null),
  ($q$conv-342$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If I______taller, I would try out for the team.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","am","be"]$q$::jsonb, 0, $q$This hypothetical condition requires the subjunctive mood, which uses 'were' with 'I' rather than the indicative 'was'; 'was' is especially tempting because it is the ordinary past tense of 'be' with 'I,' but the contrary-to-fact 'if' clause calls for the subjunctive form instead.$q$, null),
  ($q$conv-343$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Every morning she wakes early, brews coffee, and______the newspaper.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["reads","reading","to read","read"]$q$::jsonb, 0, $q$The verb must be parallel with and agree with the subject the same way 'wakes' and 'brews' do, so 'reads' is required.$q$, null),
  ($q$conv-344$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$After the long hike, the dog immediately______down by the fireplace.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["lay","laid","lied","has lain"]$q$::jsonb, 0, $q$'Lay' is the simple past tense of 'lie' (to recline); 'laid' is the past tense of the different verb 'lay' (to place something), and 'lied' means to tell a falsehood.$q$, null),
  ($q$conv-345$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After the city's old streetlights were replaced with LED fixtures______residents noticed a sharp drop in the monthly electricity bill.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After the city's old streetlights were replaced with LED fixtures' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-346$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Every evening before the audience arrives, the orchestra______its instruments in the quiet rehearsal hall.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["tunes","tune","are tuning","have tuned"]$q$::jsonb, 0, $q$'Orchestra' is a collective noun acting as a single unit, so it takes the singular verb 'tunes'; 'tune' and 'are tuning' are plural or progressive forms that don't agree, and 'have tuned' shifts to a completed action rather than the habitual present described.$q$, null),
  ($q$conv-347$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The trail was washed out after the storm______hikers had to take a longer detour around the ridge.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," and, ",": "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction between them, so a semicolon is required; a comma alone would create a comma splice, and ' and,' is not standard punctuation.$q$, null),
  ($q$conv-348$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The surprise party was planned almost entirely by my sister and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","I","myself","mine"]$q$::jsonb, 0, $q$As the object of the preposition 'by,' the pronoun must be in the objective case, 'me'; 'I' is subjective, 'myself' has no earlier reference to reflect back to, and 'mine' is possessive.$q$, null),
  ($q$conv-349$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The chef insisted on three qualities in a good broth______patience, balance, and depth.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list that explains the 'three qualities' named in the complete independent clause before it.$q$, null),
  ($q$conv-350$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Each student in the seminar must submit______essay to the committee by Friday.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["his or her","their","it's","they're"]$q$::jsonb, 0, $q$'Each' is singular, so the pronoun referring back to it must also be singular: 'his or her'; 'their' is plural, and 'it's' and 'they're' are contractions that don't function as possessives here.$q$, null),
  ($q$conv-351$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The rain finally stopped______and the children ran outside to play.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; "," ",": "]$q$::jsonb, 0, $q$Two independent clauses joined by the coordinating conjunction 'and' require a comma before it.$q$, null),
  ($q$conv-352$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the treaty was finally signed, the two nations______fighting for nearly a decade.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had been","have been","were","are"]$q$::jsonb, 0, $q$The fighting was completed before another past event (the signing), so the past perfect 'had been' is required; the other choices are present or simple past forms that don't show that earlier completion.$q$, null),
  ($q$conv-353$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The smartphone app______the startup released last spring quickly gained a million downloads.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'the startup released last spring' is essential to identifying which app is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct; 'which' requires commas for nonessential clauses, and 'who'/'whom' refer to people.$q$, null),
  ($q$conv-354$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The old oak tree finally dropped______last leaves in the November wind.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","it's","its'","their"]$q$::jsonb, 0, $q$The possessive pronoun 'its' takes no apostrophe; 'it's' is a contraction of 'it is,' 'its'' is not a standard word, and 'their' does not agree with the singular 'tree.'$q$, null),
  ($q$conv-355$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Sales dropped sharply in the first quarter______however, a new marketing strategy reversed the trend by summer.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$The conjunctive adverb 'however' joins two independent clauses and must be preceded by a semicolon, with a comma following it.$q$, null),
  ($q$conv-356$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The coach expected the team not only to practice diligently but also______their mistakes honestly.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["to acknowledge","acknowledging","acknowledges","acknowledged"]$q$::jsonb, 0, $q$The correlative pair 'not only...but also' requires parallel grammatical forms; since the first part uses the infinitive 'to practice,' the second must match with 'to acknowledge.'$q$, null),
  ($q$conv-357$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Our itinerary includes visits to museums______gardens, and historic cathedrals.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; "," ",": "]$q$::jsonb, 0, $q$Items in a series of three or more must be separated by commas.$q$, null),
  ($q$conv-358$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$I wish the weather report______more reliable before we planned the picnic around it.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","be"]$q$::jsonb, 0, $q$After 'wish,' a contrary-to-fact statement requires the subjunctive mood, which uses 'were' regardless of the subject's number; 'was' is especially tempting because it is the ordinary past tense that would fit outside a wish statement, but 'wish' specifically calls for the subjunctive.$q$, null),
  ($q$conv-359$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The museum's newest exhibit, a sprawling collection of ancient coins______fascinated visitors from around the world.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'A sprawling collection of ancient coins' is a nonessential appositive renaming the exhibit, so it must be closed with a second comma matching the one that opened it.$q$, null),
  ($q$conv-360$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Having replaced the worn brake pads just that morning, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the mechanic test-drove the car around the block.","the car was test-driven around the block.","the block was where the car was test-driven.","it was around the block that the car was test-driven."]$q$::jsonb, 0, $q$The introductory phrase 'Having replaced the worn brake pads' describes a person performing that action, so the subject immediately following must be 'the mechanic'; the other choices place the car or an unrelated word right after the modifier, creating a dangling modifier.$q$, null),
  ($q$conv-361$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Even though the ballet company had rehearsed the finale dozens of times______the lead dancer still missed her cue on opening night.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",". "]$q$::jsonb, 0, $q$'Even though the ballet company had rehearsed the finale dozens of times' is a dependent clause; ending it with a period would create a sentence fragment, so a comma is needed to join it to the independent clause that follows.$q$, null),
  ($q$conv-362$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$After the ceremony, the graduates gathered in the______lounge to celebrate with their families.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["graduates'","graduate's","graduates's","graduates"]$q$::jsonb, 0, $q$The lounge belongs to multiple graduates, so the plural noun 'graduates,' which already ends in -s, takes only an apostrophe: 'graduates''; 'graduate's' wrongly treats the noun as singular, and 'graduates's' adds a nonstandard extra s.$q$, null),
  ($q$conv-363$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The comet, ______ astronomers had tracked for nearly a year, finally became visible to the naked eye.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential, set off by commas, and refers to a thing (the comet), so 'which' is correct; 'that' is reserved for restrictive clauses, and 'who'/'whom' refer to people.$q$, null),
  ($q$conv-364$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Her daily routine includes watering the vegetable beds, pulling weeds, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["pruning the roses","to prune the roses","she prunes the roses","the roses are pruned"]$q$::jsonb, 0, $q$The list of activities must be grammatically parallel; since the earlier items use gerunds ('watering,' 'pulling'), the final item must match with the gerund 'pruning.'$q$, null),
  ($q$conv-365$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Despite the heavy rainfall earlier in the week______the river delta remained surprisingly dry.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Despite the heavy rainfall earlier in the week' is an introductory phrase and must be separated from the main clause with a comma.$q$, null),
  ($q$conv-366$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The recruiter couldn't recall______she had interviewed for the position earlier that morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","whomever","whose"]$q$::jsonb, 0, $q$'Whom' is the object of the verb 'had interviewed' ('she had interviewed whom'), so the objective case is required; 'who' is the closest trap because it would be correct if the pronoun were the subject of 'had interviewed,' which it is not.$q$, null),
  ($q$conv-367$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The pianist improvised for nearly ten minutes______the crowd never once stopped swaying to the rhythm.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," but, ",": "]$q$::jsonb, 0, $q$Both clauses are independent and closely related with no coordinating conjunction between them, so a semicolon correctly joins them; a comma alone would create a splice.$q$, null),
  ($q$conv-368$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If you have any questions about the proposal, please contact Maria or______directly.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","myself","I","mine"]$q$::jsonb, 0, $q$As the object of 'contact,' the objective pronoun 'me' is required; 'myself' is a reflexive pronoun with no earlier reference to reflect, 'I' is subjective, and 'mine' is possessive.$q$, null),
  ($q$conv-369$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The senator closed her speech with a single line the crowd would remember for years______'Progress is never owed; it is earned.'$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the quotation that follows a complete independent clause; the comma is the closest trap because commas often introduce quotations in dialogue, but Standard English convention calls for a colon when the quotation serves as a formal, emphatic conclusion to an independent clause like this one.$q$, null),
  ($q$conv-370$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$This pair of running shoes is______than the one I bought last year.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["lighter","more light","more lighter","lightest"]$q$::jsonb, 0, $q$For a one-syllable adjective like 'light,' the comparative is formed by adding '-er': 'lighter'; 'more light' and 'more lighter' are redundant or nonstandard, and 'lightest' is a superlative used for comparing three or more things.$q$, null),
  ($q$conv-371$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The observatory's roof retracted on schedule for the evening viewing______clouds rolled in and obscured the entire night sky within minutes.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction between them, so a semicolon is required; a comma alone creates a splice, and ' so,' is not standard punctuation.$q$, null),
  ($q$conv-372$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Behind the old courthouse today, there______a narrow alley lined with gas lamps.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$In this inverted sentence, the verb must agree with the delayed subject 'alley,' which is singular, so 'is' is correct; 'are' is plural, and 'were'/'have been' shift to past tense, which doesn't match the present-tense context set by 'today.'$q$, null),
  ($q$conv-373$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Thank you______Professor Alvarez, for taking the time to meet with me yesterday afternoon.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Professor Alvarez' is a direct address and must be set off from the rest of the sentence with a comma on each side; the comma after it is already given, so the blank needs a matching comma.$q$, null),
  ($q$conv-374$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Dripping with rainwater and shivering from the cold, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the hiker finally spotted a weathered cabin through the trees.","a weathered cabin stood just visible through the trees.","the trees finally thinned enough to reveal a cabin.","it was a weathered cabin that the hiker finally spotted through the trees."]$q$::jsonb, 0, $q$The introductory phrase describes a person who is dripping and shivering, so the subject immediately following the comma must be 'the hiker'; a cabin or a stand of trees cannot shiver, and restructuring the sentence with 'it was...that' still places the illogical subject 'it' right after the modifier.$q$, null),
  ($q$conv-375$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The solution turned a vivid blue______when the technician added the copper sulfate.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$When a subordinate clause like 'when the technician added the copper sulfate' follows the main clause, no comma is needed before the subordinating conjunction; adding one, or using a semicolon or colon, incorrectly breaks the sentence.$q$, null),
  ($q$conv-376$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The flight was delayed for nearly three hours______because the storm had grounded every departure since dawn.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$The subordinate clause introduced by 'because' at the end of the sentence is directly connected to the main clause, so no punctuation is needed before it; a comma, semicolon, or colon would incorrectly separate them.$q$, null),
  ($q$conv-377$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Every morning, Elena stretches for ten minutes and then______three miles before breakfast.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["runs","ran","running","to run"]$q$::jsonb, 0, $q$The verb must stay in the present tense to match 'stretches,' describing Elena's habitual routine; 'ran' shifts to past tense, and 'running'/'to run' are not finite verb forms that can pair with 'and then.'$q$, null),
  ($q$conv-378$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The artifact______according to the lead archaeologist, dates back nearly three thousand years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'According to the lead archaeologist' is a parenthetical interrupter and must be set off by commas on both sides; the comma after it is already given, so the blank requires a matching comma. The semicolon is the closest trap because semicolons can separate related independent clauses, but this interrupting phrase is not an independent clause and needs commas, not a semicolon.$q$, null),
  ($q$conv-379$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Everyone who attended the reunion______surprised by how much the old schoolhouse had changed.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","have been","are"]$q$::jsonb, 0, $q$'Everyone' is a singular indefinite pronoun and takes a singular verb, 'was'; 'were,' 'have been,' and 'are' are plural or present-tense forms that don't agree.$q$, null),
  ($q$conv-380$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The goalkeeper dove for the ball______but it slipped just past her fingertips into the net.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; "," ",": "]$q$::jsonb, 0, $q$Two independent clauses joined by the coordinating conjunction 'but' require a comma before it.$q$, null),
  ($q$conv-381$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$She is one of the finalists who______invited to present their research at the national conference.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$The relative pronoun 'who' refers to 'finalists' (plural), the antecedent in 'one of the finalists who,' so the verb must be plural: 'were.' 'Was' is the closest trap because a reader might wrongly match the verb to the singular 'she' instead of to 'finalists,' the actual antecedent of 'who.'$q$, null),
  ($q$conv-382$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The region's unemployment rate climbed for three straight months______nevertheless, job fairs across the city reported record attendance.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$The conjunctive adverb 'nevertheless' links two independent clauses and must be preceded by a semicolon, with a comma following it.$q$, null),
  ($q$conv-383$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$My two younger brothers______the vegetable garden every Saturday morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["water","waters","is watering","has watered"]$q$::jsonb, 0, $q$The plural subject 'brothers' requires the plural verb 'water'; 'waters,' 'is watering,' and 'has watered' are singular or otherwise mismatched in form.$q$, null),
  ($q$conv-384$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The negotiators finally reached an agreement after midnight______exhausted but relieved after sixteen straight hours of talks.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$The trailing phrase 'exhausted but relieved after sixteen straight hours of talks' is a nonessential description of the negotiators and must be set off with a comma. The semicolon is the closest trap because semicolons can follow an independent clause, but this trailing phrase is not itself an independent clause and needs a comma instead.$q$, null),
  ($q$conv-385$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If the electrician had checked the circuit breaker sooner, the outage______prevented entirely.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["could have been","could be","could have","can be"]$q$::jsonb, 0, $q$This past hypothetical situation requires the modal perfect 'could have been' to show an unrealized possibility in the past; 'could be' and 'can be' are present forms, and 'could have' is missing the necessary past participle 'been.'$q$, null),
  ($q$conv-386$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Waking before dawn to catch the first light______the photographer hiked nearly a mile to the overlook.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$The introductory participial phrase must be separated from the main clause with a comma.$q$, null),
  ($q$conv-387$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Training for a marathon demands far more discipline than______a single race.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["running","to run","the running of","runners who run"]$q$::jsonb, 0, $q$The comparison must use parallel grammatical forms; since 'training' is a gerund functioning as the subject's counterpart, the second half of the comparison must also be the bare gerund 'running,' not the infinitive 'to run,' the noun phrase 'the running of,' or 'runners who run,' which illogically compares discipline to people rather than to an activity.$q$, null),
  ($q$conv-388$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Maria Lopez______a self-taught engineer from a small coastal town, patented her first irrigation device at nineteen.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'A self-taught engineer from a small coastal town' is a nonessential appositive describing Maria Lopez and must be set off with a comma.$q$, null),
  ($q$conv-389$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The detective finally identified______fingerprints had been left on the broken window latch.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whose","who's","who","whom"]$q$::jsonb, 0, $q$'Whose' is the possessive form needed to show that the fingerprints belong to someone; 'who's' is a contraction of 'who is,' and 'who'/'whom' are not possessive.$q$, null),
  ($q$conv-390$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$While the neighborhood association debated the proposed noise ordinance for nearly three hours______several residents outside grew increasingly impatient.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",". "]$q$::jsonb, 0, $q$'While the neighborhood association debated the proposed noise ordinance for nearly three hours' is a dependent clause; ending it with a period would create a sentence fragment, so a comma is needed to connect it to the independent clause that follows.$q$, null),
  ($q$conv-391$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$By the ninth inning, the rain______falling so hard that the umpires finally called the game.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had begun","had began","have begun","begins"]$q$::jsonb, 0, $q$The past participle of 'begin' is 'begun,' so the correct past perfect form is 'had begun'; 'had began' incorrectly uses the simple past form as a participle, and 'have begun'/'begins' don't match the past-tense context.$q$, null),
  ($q$conv-392$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The wildfire had been contained for nearly a week______a sudden wind shift caused it to jump the containment line overnight.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction between them, so a semicolon is required; a comma alone would create a splice, and ' so,' is nonstandard punctuation.$q$, null),
  ($q$conv-393$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The chef's selection of seasonal vegetable dishes______praised by nearly every food critic in the city.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has been","have been","were","are"]$q$::jsonb, 0, $q$The subject of the sentence is 'selection,' not the intervening plural noun 'dishes,' so the singular verb 'has been' is required; 'have been,' 'were,' and 'are' incorrectly agree with the nearby plural noun instead of the true subject.$q$, null),
  ($q$conv-394$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Before starting the repair, she laid out everything she would need______a wrench, pliers, and electrical tape.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list that follows the complete independent clause.$q$, null),
  ($q$conv-395$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If gravity on the moon's surface______as strong as Earth's, astronauts could never have jumped so high.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","had been"]$q$::jsonb, 0, $q$Because the moon's weaker gravity is a constant, ongoing fact, the hypothetical requires the present subjunctive 'were,' not the past-perfect 'had been,' which would incorrectly suggest gravity itself once changed; 'was' and 'is' are not the correct subjunctive form for this contrary-to-fact statement.$q$, null),
  ($q$conv-396$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Bats navigate dense forests with remarkable precision using echolocation______many other nocturnal mammals rely primarily on scent instead.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," but, ",": "]$q$::jsonb, 0, $q$Both clauses are independent and contrast with each other with no coordinating conjunction between them, so a semicolon correctly joins them; a comma alone would create a splice.$q$, null),
  ($q$conv-397$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Of the three finalists, Priya submitted the______essay, according to every judge on the panel.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["strongest","stronger","more strong","most strong"]$q$::jsonb, 0, $q$When comparing three or more things, the superlative form is required: 'strongest'; 'stronger' compares only two things, and 'more strong'/'most strong' are nonstandard versions of the comparative and superlative.$q$, null),
  ($q$conv-398$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The biologist told the reporters______'We still don't fully understand how the species survives the winter.'$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$When a quotation follows a reporting verb like 'told,' a comma introduces it; a colon is reserved for introducing a quotation after a complete independent clause that doesn't already contain a verb of speaking directly connected to the quote.$q$, null),
  ($q$conv-399$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$This year, she resolved to exercise more, to eat healthier, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["to read more books","reading more books","more books to read","books were read more"]$q$::jsonb, 0, $q$The series must stay parallel with the earlier infinitives 'to exercise' and 'to eat,' so the final item must also be an infinitive: 'to read more books.'$q$, null),
  ($q$conv-400$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The painting's colors seemed dull under the gallery's fluorescent lights______they came alive in the afternoon sun streaming through the skylight.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," but, ",": "]$q$::jsonb, 0, $q$Both clauses are independent and closely related with no coordinating conjunction between them, so a semicolon correctly joins them; a comma alone would create a splice.$q$, null),
  ($q$conv-401$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$A number of volunteers from the community college______up early to help rebuild the playground.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["showed","shows","has shown","is showing"]$q$::jsonb, 0, $q$'A number of' functions as a plural quantifier meaning 'several' and takes a plural verb, 'showed.' 'Has shown' is the closest trap because it would be correct if the phrase were 'the number of volunteers,' which treats the group as a single unit rather than as individuals.$q$, null),
  ($q$conv-402$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The band played three encores______yet the crowd still begged for one more song.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; "," ",": "]$q$::jsonb, 0, $q$Two independent clauses joined by the coordinating conjunction 'yet' require a comma before it.$q$, null),
  ($q$conv-403$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Her physical therapist recommended both strengthening her core and______her shoulders to prevent further injury.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["stretching","to stretch","she stretches","the stretch of"]$q$::jsonb, 0, $q$The correlative pair 'both...and' requires parallel forms; since the first part uses the gerund 'strengthening,' the second must match with 'stretching.'$q$, null),
  ($q$conv-404$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The auction catalog listed a Victorian writing desk, valued at several thousand dollars______a pair of hand-carved chairs, each over a century old; and a porcelain tea set from the same estate.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," and ",": "]$q$::jsonb, 0, $q$Because each item in this list already contains an internal comma, semicolons are needed to separate the three main items clearly. The comma is the closest trap because commas normally separate list items, but using only commas here would blur where one item ends and the next begins.$q$, null),
  ($q$conv-405$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The biographer, ______ spent six years researching the reclusive author's life, finally published the long-awaited book.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","whom","which","whose"]$q$::jsonb, 0, $q$Within the nonessential clause, the pronoun functions as the subject of the verb 'spent,' so the subjective 'who' is required; 'whom' is the closest trap because it is the correct choice when the pronoun is the object of a verb or preposition within its clause, which is not the case here.$q$, null),
  ($q$conv-406$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The curtain rose precisely on time______the understudy, not the usual lead, stepped into the spotlight.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction linking them, so a semicolon is required. The comma is the closest trap because a comma plus 'so' could join these clauses correctly, but a bare comma alone creates a comma splice.$q$, null),
  ($q$conv-407$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After the rain stopped______ the children ran outside to play in the puddles.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",", ","; ",": "]$q$::jsonb, 1, $q$The introductory dependent clause ('After the rain stopped') must be followed by a comma before the main clause begins.$q$, null),
  ($q$conv-408$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The museum opens at nine in the morning______ it closes at five in the afternoon.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",": ","; ",", "]$q$::jsonb, 2, $q$Two independent clauses with no conjunction need a semicolon. A comma alone would create a comma splice, and no punctuation would create a run-on.$q$, null),
  ($q$conv-409$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The recipe calls for four ingredients______ flour, eggs, butter, and sugar.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",": ","; ",", "]$q$::jsonb, 1, $q$A colon correctly follows the complete independent clause to introduce the list that specifies the four ingredients.$q$, null),
  ($q$conv-410$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Maria had hoped to attend the concert______ but her flight was delayed by a snowstorm.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",", ",": ","; "]$q$::jsonb, 1, $q$A comma is needed before the coordinating conjunction 'but' when it joins two independent clauses.$q$, null),
  ($q$conv-411$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$My neighbor, a retired pilot______ grows prize-winning tomatoes in her backyard.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["","; ",", ",": "]$q$::jsonb, 2, $q$The appositive 'a retired pilot' is nonessential, so it must be closed with a comma to match the comma that opened it.$q$, null),
  ($q$conv-412$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Dr. Okafor's lecture focused on a single question______ how do city lights affect migrating birds?$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","",": ","; "]$q$::jsonb, 2, $q$A colon after the independent clause introduces the specific question the lecture addressed.$q$, null),
  ($q$conv-413$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The storm knocked out power across the county______ however, crews restored service within a few hours.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",": ","",", "]$q$::jsonb, 0, $q$A semicolon should precede a conjunctive adverb like 'however' when it connects two independent clauses; a comma there would create a comma splice.$q$, null),
  ($q$conv-414$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The hikers carried everything they would need for the overnight trip______ tents, sleeping bags, stoves, and enough food for two days.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ","",": "]$q$::jsonb, 3, $q$The independent clause is complete, and what follows lists the items, so a colon is the proper punctuation.$q$, null),
  ($q$conv-415$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The author's first novel, which was published in 1998______ became a surprise bestseller.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",": ",", ",""]$q$::jsonb, 2, $q$The nonrestrictive clause 'which was published in 1998' began after a comma and must end with a comma.$q$, null),
  ($q$conv-416$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Some historians argue that the library at Alexandria was destroyed in a single fire______ others contend that it declined slowly over several centuries.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",": ","; ",", "]$q$::jsonb, 2, $q$Two complete, closely related ideas are joined by a semicolon. A comma alone would be a comma splice.$q$, null),
  ($q$conv-417$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Native to the high deserts of Chile______ the plant stores water in its thick, waxy leaves.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","",": ","; "]$q$::jsonb, 0, $q$The introductory participial phrase modifies 'the plant' and should be followed by a comma.$q$, null),
  ($q$conv-418$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The new policy has one clear goal______ to reduce the time residents spend waiting for permits.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ","",": "]$q$::jsonb, 3, $q$A colon introduces the explanation of the single goal that the first clause announces.$q$, null),
  ($q$conv-419$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Marie Curie won Nobel Prizes in two different sciences______ physics and chemistry.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ","",": ",", but"]$q$::jsonb, 2, $q$The words after the blank specify which two sciences, so a colon after the complete clause is appropriate.$q$, null),
  ($q$conv-420$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The conductor raised her baton______ the orchestra fell silent.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ",": ","; ",""]$q$::jsonb, 2, $q$Both parts are independent clauses with no conjunction, so a semicolon is required.$q$, null),
  ($q$conv-421$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The bakery on Fifth Street sells three kinds of bread______ sourdough, rye, and a seeded multigrain.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",": ","; ",", "]$q$::jsonb, 1, $q$A colon follows a complete clause and introduces the list that names the three breads.$q$, null),
  ($q$conv-422$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Although the experiment had failed twice______ the team decided to try one more time.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ","",": "]$q$::jsonb, 1, $q$The subordinate clause beginning with 'Although' must be separated from the main clause by a comma.$q$, null),
  ($q$conv-423$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Ms. Alvarez, who coaches the debate team______ was named teacher of the year.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": ",""]$q$::jsonb, 1, $q$The nonessential relative clause is set off by a pair of commas; a closing comma is needed before the verb 'was'.$q$, null),
  ($q$conv-424$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The river flooded the lower fields______ the farmers lost nearly their entire spring planting.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ","",": while",", "]$q$::jsonb, 0, $q$Two independent clauses joined without a conjunction require a semicolon.$q$, null),
  ($q$conv-425$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The city's tallest building was completed in 1931______ at the time, it was the tallest in the world.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",""]$q$::jsonb, 1, $q$'At the time, it was the tallest in the world' is an independent clause, so a semicolon (not a comma) must separate the two clauses.$q$, null),
  ($q$conv-426$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Researchers who study sleep have identified a surprising factor in teenagers' fatigue______ school start times.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": ",""]$q$::jsonb, 2, $q$The independent clause promises a specific factor, and the fragment 'school start times' names it, so a colon is appropriate.$q$, null),
  ($q$conv-427$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The film, praised by critics for its restrained performances______ received no major awards.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","","; ",", "]$q$::jsonb, 3, $q$The phrase 'praised by critics for its restrained performances' is a nonessential modifier opened by a comma and must be closed by a comma.$q$, null),
  ($q$conv-428$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Whether the bridge can be saved______ depends on the results of next month's engineering survey.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","",", ","; "]$q$::jsonb, 1, $q$The noun clause 'Whether the bridge can be saved' is the subject of 'depends', and a subject must not be separated from its verb by punctuation.$q$, null),
  ($q$conv-429$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The committee's final report recommended three changes______ extending library hours, adding bus routes, and funding after-school programs.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ","—and",", "]$q$::jsonb, 0, $q$A colon follows the independent clause and introduces the three recommended changes.$q$, null),
  ($q$conv-430$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The telescope's mirror, polished to within a fraction of the wavelength of light______ allowed astronomers to image distant galaxies in unprecedented detail.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["","; ",": ",", "]$q$::jsonb, 3, $q$The participial phrase interrupts the sentence between the subject and its verb, so it must be closed with a comma.$q$, null),
  ($q$conv-431$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Not every proposal was approved______ the board rejected the two most expensive ones outright.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[":",", ",", and","; "]$q$::jsonb, 3, $q$The second independent clause elaborates on the first; a semicolon joins them correctly, whereas a comma alone would be a splice.$q$, null),
  ($q$conv-432$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Beethoven's late quartets were considered bafflingly strange by many of his contemporaries______ today they are regarded as among the greatest works in the repertoire.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ",", ","","; "]$q$::jsonb, 3, $q$Two contrasting independent clauses need a semicolon (or a comma plus a conjunction).$q$, null),
  ($q$conv-433$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The ship's captain, hoping to avoid the worst of the weather______ altered course twice during the night.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",", ","; ",": "]$q$::jsonb, 1, $q$The participial phrase is nonessential and sits between the subject and verb, so it is closed with a comma.$q$, null),
  ($q$conv-434$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$My brother plays the cello______ my sister plays the flute.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","",", ","; "]$q$::jsonb, 3, $q$Two independent clauses with no conjunction require a semicolon.$q$, null),
  ($q$conv-435$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Please bring the following to the exam______ two pencils, a calculator, and a photo ID.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ","",", ",": "]$q$::jsonb, 3, $q$A colon follows the complete clause and introduces the list of items.$q$, null),
  ($q$conv-436$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The study's results were inconclusive______ the sample was too small to reveal any meaningful pattern.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","",": ","; but"]$q$::jsonb, 2, $q$The second clause explains why the results were inconclusive, so a colon (or semicolon) fits; a comma would create a splice.$q$, null),
  ($q$conv-437$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Anna loves hiking in the mountains______ and her brother prefers kayaking on the lake.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["",": ","; ",", "]$q$::jsonb, 3, $q$A comma is needed before the coordinating conjunction 'and' joining two independent clauses.$q$, null),
  ($q$conv-438$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The mayor's announcement caught many residents off guard______ it contradicted her earlier promise to freeze property taxes.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ",": which","","; "]$q$::jsonb, 3, $q$The second independent clause is closely related to the first and is joined with a semicolon; a comma alone is a splice.$q$, null),
  ($q$conv-439$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Because the soil in the valley is unusually rich in volcanic minerals______ vineyards there produce grapes with a distinctive flavor.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ","",", ",": "]$q$::jsonb, 2, $q$The dependent clause introduced by 'Because' must be followed by a comma before the main clause.$q$, null),
  ($q$conv-440$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The collection of rare stamps______ displayed in a glass case near the entrance.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have been","were","is","are"]$q$::jsonb, 2, $q$The subject 'collection' is singular, so the singular verb 'is' is required.$q$, null),
  ($q$conv-441$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Each of the students______ responsible for submitting a final project.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","were","have been","is"]$q$::jsonb, 3, $q$'Each' is singular and takes a singular verb.$q$, null),
  ($q$conv-442$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The twins asked ______ parents to drive them to the game.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","there","they're","its"]$q$::jsonb, 0, $q$The possessive pronoun 'their' agrees with the plural 'twins'.$q$, null),
  ($q$conv-443$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Yesterday, the team ______ its final practice before the tournament.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["held","holds","will hold","has holding"]$q$::jsonb, 0, $q$'Yesterday' calls for the simple past tense, 'held'.$q$, null),
  ($q$conv-444$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Neither the director nor the actors______ satisfied with the first rehearsal.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has been","is","was","were"]$q$::jsonb, 3, $q$With 'neither…nor', the verb agrees with the nearer subject, 'actors', which is plural.$q$, null),
  ($q$conv-445$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The books on the top shelf, which ______ mostly poetry collections, belonged to her grandmother.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","has been","is"]$q$::jsonb, 0, $q$The relative pronoun 'which' refers to the plural 'books', so the plural verb 'were' is required, and the past tense matches 'belonged'.$q$, null),
  ($q$conv-446$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Walking along the shore at dawn, ______$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["the dolphins' appearance was noticed just beyond the breakers.","the hikers noticed a pod of dolphins just beyond the breakers.","a pod of dolphins appeared just beyond the breakers for the hikers.","dolphins were noticed by the hikers just beyond the breakers."]$q$::jsonb, 1, $q$The introductory participial phrase 'Walking along the shore at dawn' must modify the noun that follows, and only the hikers could be walking.$q$, null),
  ($q$conv-447$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The scientist, along with her two assistants, ______ the data before submitting the paper.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["review","were reviewing","have reviewed","reviewed"]$q$::jsonb, 3, $q$The subject is the singular 'scientist'; 'along with her two assistants' is a parenthetical, so the singular-compatible past tense 'reviewed' is correct.$q$, null),
  ($q$conv-448$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The reporter asked the candidate ______ she believed would best serve the district.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","which","whose","who"]$q$::jsonb, 3, $q$The pronoun is the subject of 'would best serve'; 'she believed' is parenthetical. A subject takes 'who', not 'whom'.$q$, null),
  ($q$conv-449$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Because Priya had practiced every day, she ______ the piece flawlessly at the recital.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is performing","will perform","performed","performs"]$q$::jsonb, 2, $q$The surrounding past-perfect context ('had practiced') and 'at the recital' establish a past event, so the past tense 'performed' fits.$q$, null),
  ($q$conv-450$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new library offers more programs than ______ in the neighboring town.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["those","that of","it","the one"]$q$::jsonb, 3, $q$The comparison is between the library's programs and the neighboring town's library, so the singular referent 'the one' (the library) is appropriate.$q$, null),
  ($q$conv-451$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Having finished the exam early, ______$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["Jonas's answers were double-checked in the extra time.","an extra review of the answers was made by Jonas.","the extra time was used by Jonas to double-check his answers.","Jonas used the extra time to double-check his answers."]$q$::jsonb, 3, $q$The participial phrase 'Having finished the exam early' must modify Jonas, the person who finished.$q$, null),
  ($q$conv-452$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The committee ______ divided in their opinions about the proposal, with half favoring it and half opposed.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have been","were","are","was"]$q$::jsonb, 3, $q$Even when members disagree, 'committee' as a unit takes a singular verb; 'was' is correct.$q$, null),
  ($q$conv-453$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Increasing the sample size reduces random error, and ______ the results more reliable.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["makes","to make","make","making"]$q$::jsonb, 0, $q$The verb 'makes' is parallel to 'reduces' and agrees with the gerund subject 'increasing'.$q$, null),
  ($q$conv-454$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The designer's aim was to create a space that felt open, inviting, and ______$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that people of all ages could feel welcome.","it welcomed people of all ages.","welcoming to people of all ages.","to welcome people of all ages."]$q$::jsonb, 2, $q$The series 'open, inviting, and ___' requires parallel adjectives, so 'welcoming to people of all ages' keeps the list parallel.$q$, null),
  ($q$conv-455$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Of the two proposals, the second is ______$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["the most cost-effectively.","the more cost-effective.","the most cost-effective.","more cost-effective than it."]$q$::jsonb, 1, $q$When comparing two things, the comparative ('more') is used, not the superlative.$q$, null),
  ($q$conv-456$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The volcano's eruption in 1980 ______ the surrounding forest and altered the landscape for decades.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["devastating","devastated","devastates","had devastating"]$q$::jsonb, 1, $q$A past-tense verb is needed to match 'eruption in 1980' and the parallel verb 'altered'.$q$, null),
  ($q$conv-457$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Their neighbor ______ new dog barks every morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["'s"," is","s'","s"]$q$::jsonb, 0, $q$The possessive 'neighbor's' shows ownership by the singular noun 'neighbor'.$q$, null),
  ($q$conv-458$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Not only the manager but also the interns ______ attending the workshop.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$With 'not only…but also', the verb agrees with the nearer subject, 'interns', so the plural 'are' is correct.$q$, null),
  ($q$conv-459$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The rate at which glaciers retreat, like the rates of many other natural processes, ______ over time.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["varies","are varying","vary","have varied"]$q$::jsonb, 0, $q$The subject is the singular 'rate'; the intervening phrases do not change its number.$q$, null),
  ($q$conv-460$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Last summer, we ______ to the coast, where we spent a week hiking and swimming.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["will travel","have traveled","travel","traveled"]$q$::jsonb, 3, $q$'Last summer' establishes a completed past action, so the simple past 'traveled' is correct.$q$, null),
  ($q$conv-461$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The report, which examined three decades of rainfall data, ______ that droughts have become more frequent in the region.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["concluding","to conclude","concludes","conclude"]$q$::jsonb, 2, $q$The singular subject 'report' takes the singular present verb 'concludes'; the 'which' clause is a nonessential modifier.$q$, null),
  ($q$conv-462$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Several of the paintings ______ been restored.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has","is","was","have"]$q$::jsonb, 3, $q$The plural subject 'Several' requires the plural auxiliary 'have'.$q$, null),
