  ($q$alg-102$q$, $q$math$q$, $q$Algebra$q$, $q$Linear equations in one variable$q$, 2, null, $q$A plumber charges $45 for a service call plus $60 per hour of work. If a repair bill totaled $225, how many hours did the repair take?$q$, $q$["3","4","2","180"]$q$::jsonb, 0, $q$45 + 60h = 225 → 60h = 180 → h = 3.$q$, null),
  ($q$alg-103$q$, $q$math$q$, $q$Algebra$q$, $q$Linear equations in one variable$q$, 1, null, $q$If 5(x + 2) − 3(x − 1) = 21, what is the value of x?$q$, $q$["4","8","−4","17"]$q$::jsonb, 0, $q$5(x + 2) − 3(x − 1) = 21 → 5x + 10 − 3x + 3 = 21 → 2x + 13 = 21 → x = 4.$q$, null),
